func ikiliArama(array liste, int hedef): int {
  int alt = 0;
  int ust = length(liste) - 1;
  while (alt <= ust) {
    int orta = toInt((alt + ust) / 2);
    if (liste[orta] == hedef) {
      return orta;
    } else if (liste[orta] < hedef) {
      alt = orta + 1;
    } else {
      ust = orta - 1;
    }
  }
  return -1;
}

