func siniflandir(json arr): str {
    return match arr {
        []              => "bos",
        [x]             => "tek: " + toString(x),
        [a, b]          => "cift: " + toString(a) + "," + toString(b),
        [head, ..tail]  => toString(head) + " + " + toString(length(tail)) + " tane daha",
        _               => "?"
    };
}

