// 'dene'/'yakala'/'sonunda'/'firlat', Tulpar'da try/catch/finally/throw'un Türkçe karşılıklarıdır; tanımlayıcı olarak kullanılamaz.
func guvenliBolme(int a, int b) {
    if (b == 0) {
        throw "sifira bolunemez";
    }
    return a / b;
}

try {
    print(guvenliBolme(10, 0));
} catch (hata) {
    print("hata olustu:", hata);
}

